CREATE TABLE content_fact (id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY, canonical_key VARCHAR(128) NOT NULL UNIQUE, subject_code VARCHAR(40) NOT NULL, emoji VARCHAR(24), status VARCHAR(24) NOT NULL DEFAULT 'DRAFT' CHECK(status IN ('DRAFT','IN_REVIEW','PUBLISHED','RETIRED')), verified_at TIMESTAMPTZ, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE content_fact_translation (fact_id BIGINT NOT NULL REFERENCES content_fact(id) ON DELETE CASCADE,locale VARCHAR(12) NOT NULL,body TEXT NOT NULL,PRIMARY KEY(fact_id,locale));
CREATE TABLE content_fact_audience (fact_id BIGINT NOT NULL REFERENCES content_fact(id) ON DELETE CASCADE,audience VARCHAR(16) NOT NULL CHECK(audience IN ('STUDENT','EXPLORE')),grade_level INTEGER CHECK(grade_level BETWEEN 1 AND 12),CHECK ((audience='STUDENT' AND grade_level IS NOT NULL) OR (audience='EXPLORE' AND grade_level IS NULL)));
CREATE UNIQUE INDEX uq_fact_audience_grade ON content_fact_audience(fact_id,audience,COALESCE(grade_level,0));
CREATE TABLE content_source (id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY, fact_id BIGINT NOT NULL REFERENCES content_fact(id) ON DELETE CASCADE,source_url TEXT NOT NULL,source_title TEXT NOT NULL,checked_at TIMESTAMPTZ);
CREATE TABLE quiz_question (id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,fact_id BIGINT NOT NULL REFERENCES content_fact(id),status VARCHAR(24) NOT NULL DEFAULT 'DRAFT' CHECK(status IN ('DRAFT','IN_REVIEW','PUBLISHED','RETIRED')));
CREATE TABLE quiz_question_translation (question_id BIGINT NOT NULL REFERENCES quiz_question(id) ON DELETE CASCADE,locale VARCHAR(12) NOT NULL,prompt TEXT NOT NULL,explanation TEXT NOT NULL,PRIMARY KEY(question_id,locale));
CREATE TABLE quiz_option (id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,question_id BIGINT NOT NULL REFERENCES quiz_question(id) ON DELETE CASCADE,position SMALLINT NOT NULL CHECK(position>=0),correct BOOLEAN NOT NULL DEFAULT FALSE, UNIQUE(question_id,position));
CREATE TABLE quiz_option_translation (option_id BIGINT NOT NULL REFERENCES quiz_option(id) ON DELETE CASCADE,locale VARCHAR(12) NOT NULL,body TEXT NOT NULL,PRIMARY KEY(option_id,locale));
CREATE INDEX idx_facts_published ON content_fact(status,verified_at,id);
CREATE INDEX idx_fact_audiences ON content_fact_audience(audience,grade_level,fact_id);
CREATE INDEX idx_sources_checked ON content_source(fact_id,checked_at);
CREATE INDEX idx_questions_published ON quiz_question(status,fact_id,id);
